import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';

import { DevotionalRoutingModule } from './devotional-routing-module';
import { DevotionalItem } from './devotional-item/devotional-item';
import { DevotionalContent } from './devotional-content/devotional-content';
import { UrlSerializer } from '@angular/router';
import { cleanUrlSerializer } from '../utils/clean-url-serializer';
import { DevotionalBookModule } from './devotional-book/devotional-book-module';
import { DevotionalMultimediaModule } from './devotional-multimedia/devotional-multimedia-module';
import { DevotionalMarketModule } from './devotional-market/devotional-market-module';
import { DevotionalEventModule } from './devotional-event/devotional-event-module';
import { DevotionalHealthModule } from './devotional-health/devotional-health-module';
import { DevotionalWealthModule } from './devotional-wealth/devotional-wealth-module';

@NgModule({
  declarations: [DevotionalContent, DevotionalItem],
  imports: [
    CommonModule,
    DevotionalRoutingModule,
    DevotionalBookModule,
    DevotionalMultimediaModule,
    DevotionalMarketModule,
    DevotionalEventModule,
    DevotionalHealthModule,
    DevotionalWealthModule,
  ],
  exports: [DevotionalContent, DevotionalItem, DevotionalRoutingModule],
  providers: [
    {
      provide: UrlSerializer,
      useClass: cleanUrlSerializer,
    },
  ],
})
export class DevotionalModule {
  
}
